"""Money rules. All amounts are integer cents."""
import os
import sys
import tomllib
from decimal import Decimal

_HERE = os.path.dirname(os.path.abspath(__file__))

try:
    if _HERE not in sys.path:
        sys.path.insert(0, _HERE)
    from vendor.rounding import round_cents
except Exception:  # pragma: no cover - fallback with identical behaviour
    import math

    def round_cents(value, mode="ROUND_HALF_EVEN"):
        d = Decimal(str(value))
        if mode == "ROUND_HALF_UP":
            return int(math.floor(d + Decimal("0.5")))
        return int(d.quantize(Decimal(1), rounding=mode))


def load_data(path=None):
    path = path or os.path.join(_HERE, "data.toml")
    with open(path, "rb") as f:
        return tomllib.load(f)


def list_price(unit_cost, markup, mode):
    """C08: unit_cost * (1 + markup), rounded to a whole cent."""
    return round_cents(Decimal(unit_cost) * (1 + Decimal(str(markup))), mode)


def sale_revenue(price, qty, bulk_threshold, bulk_discount_pct, mode):
    """C07/C09: price*qty, with bulk discount for qty >= threshold."""
    pct = bulk_discount_pct if qty >= bulk_threshold else 0
    return round_cents(Decimal(price * qty * (100 - pct)) / 100, mode)


def storage_charge(units, cents_per_unit_day):
    """C19."""
    return units * cents_per_unit_day


def transfer_cost(qty, cents_per_unit):
    """C11 (see notes on sign)."""
    return qty * cents_per_unit


def delivery_payment(unit_cost, qty, late, late_penalty_pct, mode):
    """C18: late deliveries are paid less by the late-penalty percentage."""
    base = unit_cost * qty
    if not late:
        return base
    return round_cents(Decimal(base * (100 - late_penalty_pct)) / 100, mode)


def turnover(shipped, held_samples):
    """C30: units shipped / average units held; None if average is 0."""
    if not held_samples:
        return None
    total = sum(held_samples)
    if total == 0:
        return None
    return shipped / (total / len(held_samples))
