"""Depot: multi-warehouse inventory and cash ledger."""
import copy
import json

import events
import money
import suppliers
from events import emit, check_cash


class DepotError(Exception):
    def __init__(self, code):
        super().__init__(code)
        self.code = code


_STATE_KEYS = {
    "cash", "day", "items", "lots", "shipped", "returned", "shipments",
    "held_log", "fired", "notes", "overdrawn", "suppliers", "orders",
    "next_order",
}


class Depot:
    def __init__(self, warehouses, capacities, opening_cash, rounding_mode,
                 late_penalty_pct=None, config=None):
        self._whs = list(warehouses)
        self._caps = dict(capacities)
        for w in self._whs:
            if w not in self._caps:
                raise DepotError("UNKNOWN_WAREHOUSE")
        self._mode = rounding_mode
        self._late_pct = late_penalty_pct  # owner's decision; no default
        self._cfg = config if config is not None else money.load_data()
        self._st = {
            "cash": int(opening_cash), "day": 0, "items": {}, "lots": {},
            "shipped": {}, "returned": {}, "shipments": [],
            "held_log": {"0": 0}, "fired": [], "notes": [],
            "overdrawn": False, "suppliers": {}, "orders": {},
            "next_order": 1,
        }
        self._undo = None
        check_cash(self._st)

    # ---------- infrastructure ----------
    def _run(self, fn, undoable=True):
        snap = copy.deepcopy(self._st)
        try:
            result = fn(self._st)
        except BaseException:
            self._st = snap
            raise
        self._undo = snap if undoable else None
        return result

    def _sku(self, sku):
        if sku not in self._st["items"]:
            raise DepotError("UNKNOWN_SKU")
        return self._st["items"][sku]

    def _wh(self, wh):
        if wh not in self._whs:
            raise DepotError("UNKNOWN_WAREHOUSE")

    @staticmethod
    def _qty(qty):
        if type(qty) is not int or qty <= 0:
            raise DepotError("INVALID_QTY")

    def _units(self, wh):
        return sum(sum(q for _, q in self._st["lots"][s][wh])
                   for s in self._st["lots"])

    def _held(self, sku, wh):
        return sum(q for _, q in self._st["lots"][sku][wh])

    def _total_units(self):
        return sum(self._units(w) for w in self._whs)

    def _touch(self, sku, wh):
        if self._held(sku, wh) > self._st["items"][sku]["reorder"]:
            f = [sku, wh]
            if f in self._st["fired"]:
                self._st["fired"].remove(f)

    def _take(self, sku, wh, qty):
        lots = self._st["lots"][sku][wh]
        taken = []
        while qty > 0:
            d, q = lots[0]
            use = min(q, qty)
            taken.append([d, use])
            qty -= use
            if use == q:
                lots.pop(0)
            else:
                lots[0][1] -= use
        return taken

    def _receive_core(self, sku, qty, wh, cost):
        st = self._st
        self._sku(sku)
        self._wh(wh)
        self._qty(qty)
        if st["cash"] < 0:
            raise DepotError("OVERDRAWN")
        if self._units(wh) + qty > self._caps[wh]:
            raise DepotError("CAPACITY")
        if st["cash"] - cost < 0:
            raise DepotError("INSUFFICIENT_FUNDS")
        st["cash"] -= cost
        st["lots"][sku][wh].append([st["day"], qty])
        self._touch(sku, wh)
        check_cash(st)

    # ---------- properties ----------
    @property
    def cash(self):
        return self._st["cash"]

    @property
    def day(self):
        return self._st["day"]

    # ---------- items ----------
    def add_item(self, sku, unit_cost, reorder_level, shelf_life_days=None):
        def f(st):
            if sku in st["items"]:
                raise DepotError("DUPLICATE_SKU")
            if type(unit_cost) is not int or unit_cost <= 0:
                raise DepotError("INVALID_COST")
            if type(reorder_level) is not int or reorder_level < 0:
                raise DepotError("INVALID_REORDER_LEVEL")
            if shelf_life_days is not None and (
                    type(shelf_life_days) is not int or shelf_life_days < 1):
                raise DepotError("INVALID_SHELF_LIFE")
            st["items"][sku] = {"cost": unit_cost, "reorder": reorder_level,
                                "shelf": shelf_life_days}
            st["lots"][sku] = {w: [] for w in self._whs}
            st["shipped"][sku] = 0
            st["returned"][sku] = 0
        self._run(f)

    def list_price(self, sku):
        it = self._sku(sku)
        return money.list_price(it["cost"], self._cfg["markup"], self._mode)

    # ---------- stock movement ----------
    def receive(self, sku, qty, wh):
        def f(st):
            it = self._sku(sku)
            self._receive_core(sku, qty, wh, it["cost"] * qty
                               if type(qty) is int else 0)
        self._run(f)

    def receive_bulk(self, receipts):
        def f(st):
            for sku, qty, wh in receipts:
                it = self._sku(sku)
                self._receive_core(sku, qty, wh, it["cost"] * qty
                                   if type(qty) is int else 0)
        self._run(f)

    def ship(self, sku, qty, wh, price):
        def f(st):
            it = self._sku(sku)
            self._wh(wh)
            self._qty(qty)
            if self._held(sku, wh) < qty:
                raise DepotError("INSUFFICIENT_STOCK")
            self._take(sku, wh, qty)
            st["cash"] += money.sale_revenue(
                price, qty, self._cfg["bulk_threshold"],
                self._cfg["bulk_discount_pct"], self._mode)
            st["shipped"][sku] += qty
            st["shipments"].append([st["day"], qty])
            left = self._held(sku, wh)
            if left <= it["reorder"] and [sku, wh] not in st["fired"]:
                st["fired"].append([sku, wh])
                emit(st, "REORDER", sku, wh)
            check_cash(st)
        self._run(f)

    def transfer(self, sku, qty, from_wh, to_wh):
        def f(st):
            self._sku(sku)
            self._wh(from_wh)
            self._wh(to_wh)
            self._qty(qty)
            if from_wh == to_wh:
                raise DepotError("SAME_WAREHOUSE")
            if self._held(sku, from_wh) < qty:
                raise DepotError("INSUFFICIENT_STOCK")
            if self._units(to_wh) + qty > self._caps[to_wh]:
                raise DepotError("CAPACITY")
            cost = money.transfer_cost(
                qty, self._cfg["transfer_credit_cents_per_unit"])
            if st["cash"] - cost < 0:
                raise DepotError("INSUFFICIENT_FUNDS")
            st["cash"] -= cost
            moved = self._take(sku, from_wh, qty)
            dest = st["lots"][sku][to_wh]
            dest.extend(moved)
            dest.sort(key=lambda l: l[0])
            self._touch(sku, from_wh)
            self._touch(sku, to_wh)
            check_cash(st)
        self._run(f)

    def return_goods(self, sku, qty, wh, price):
        def f(st):
            it = self._sku(sku)
            self._wh(wh)
            self._qty(qty)
            if st["returned"][sku] + qty > st["shipped"][sku]:
                raise DepotError("RETURN_EXCEEDS")
            if it["shelf"] is not None:
                # Owner has not decided restock vs discard.
                raise DepotError("RETURN_POLICY_UNDECIDED")
            if self._units(wh) + qty > self._caps[wh]:
                raise DepotError("CAPACITY")
            st["lots"][sku][wh].append([st["day"], qty])
            st["cash"] -= price * qty
            st["returned"][sku] += qty
            self._touch(sku, wh)
            check_cash(st)
        self._run(f)

    # ---------- time ----------
    def advance_day(self):
        def f(st):
            st["day"] += 1
            today = st["day"]
            units = self._total_units()
            st["cash"] -= money.storage_charge(
                units, self._cfg["storage_cents_per_unit_day"])
            for sku in sorted(st["items"]):
                shelf = st["items"][sku]["shelf"]
                if shelf is None:
                    continue
                for wh in sorted(self._whs):
                    lots = st["lots"][sku][wh]
                    gone = sum(q for d, q in lots if today - d > shelf)
                    if gone:
                        st["lots"][sku][wh] = [
                            l for l in lots if today - l[0] <= shelf]
                        emit(st, "EXPIRY", sku, wh, gone)
            check_cash(st)
            st["held_log"][str(today)] = self._total_units()
        self._run(f, undoable=False)

    # ---------- suppliers ----------
    def place_order(self, supplier, sku, qty, due_day, wh=None):
        def f(st):
            self._sku(sku)
            self._qty(qty)
            target = wh if wh is not None else self._whs[0]
            self._wh(target)
            suppliers.ensure(st, supplier)
            if suppliers.is_suspended(st, supplier):
                # keep the supplier record created; nothing else changes
                raise DepotError("SUPPLIER_SUSPENDED")
            oid = st["next_order"]
            st["next_order"] += 1
            st["orders"][str(oid)] = {
                "supplier": supplier, "sku": sku, "qty": qty,
                "due": due_day, "wh": target, "done": False}
            return oid
        return self._run(f)

    def deliver(self, order_id, day):
        def f(st):
            o = st["orders"].get(str(order_id))
            if o is None:
                raise DepotError("UNKNOWN_ORDER")
            if o["done"]:
                raise DepotError("ALREADY_DELIVERED")
            late = day > o["due"]
            if late and self._late_pct is None:
                raise DepotError("LATE_PENALTY_UNSET")
            it = st["items"][o["sku"]]
            pay = money.delivery_payment(it["cost"], o["qty"], late,
                                         self._late_pct, self._mode)
            self._receive_core(o["sku"], o["qty"], o["wh"], pay)
            o["done"] = True
            suppliers.adjust(st, o["supplier"], -1 if late else 1)
        self._run(f)

    def reinstate(self, supplier):
        def f(st):
            if supplier not in st["suppliers"]:
                raise DepotError("UNKNOWN_SUPPLIER")
            suppliers.reinstate(st, supplier)
        self._run(f)

    def reliability(self, supplier):
        if supplier not in self._st["suppliers"]:
            raise DepotError("UNKNOWN_SUPPLIER")
        return self._st["suppliers"][supplier]["rel"]

    # ---------- queries ----------
    def stock(self, sku, wh=None):
        self._sku(sku)
        if wh is not None:
            self._wh(wh)
            return self._held(sku, wh)
        return sum(self._held(sku, w) for w in self._whs)

    def report(self):
        rows = []
        for sku in sorted(self._st["items"]):
            for wh in sorted(self._whs):
                u = self._held(sku, wh)
                rows.append((sku, wh, u, u * self._st["items"][sku]["cost"]))
        return rows

    def notifications(self):
        return [tuple(n) for n in self._st["notes"]]

    def turnover(self, start_day, end_day):
        st = self._st
        shipped = sum(q for d, q in st["shipments"]
                      if start_day <= d <= end_day)
        samples = []
        for d in range(start_day, end_day + 1):
            if d == st["day"]:
                samples.append(self._total_units())
            elif str(d) in st["held_log"]:
                samples.append(st["held_log"][str(d)])
        return money.turnover(shipped, samples)

    def audit(self, counts):
        def f(st):
            if not counts:
                raise DepotError("EMPTY_AUDIT")
            for (sku, wh) in counts:
                self._sku(sku)
                self._wh(wh)
            for (sku, wh) in sorted(counts):
                ledger = self._held(sku, wh)
                if ledger != counts[(sku, wh)]:
                    emit(st, "AUDIT_MISMATCH", sku, wh, ledger,
                         counts[(sku, wh)])
        self._run(f)

    # ---------- undo / persistence ----------
    def undo(self):
        if self._undo is None:
            raise DepotError("UNDO_BLOCKED")
        self._st = self._undo
        self._undo = None

    def save(self):
        return json.dumps({"version": 1, "state": self._st}, sort_keys=True)

    def load(self, s):
        try:
            d = json.loads(s)
            if not isinstance(d, dict) or d.get("version") != 1:
                raise ValueError
            st = d["state"]
            if not isinstance(st, dict) or set(st) != _STATE_KEYS:
                raise ValueError
            if type(st["cash"]) is not int or type(st["day"]) is not int:
                raise ValueError
            for sku, it in st["items"].items():
                if set(it) != {"cost", "reorder", "shelf"}:
                    raise ValueError
                if set(st["lots"][sku]) != set(self._whs):
                    raise ValueError
                for wh, lots in st["lots"][sku].items():
                    for d_, q in lots:
                        if type(d_) is not int or type(q) is not int:
                            raise ValueError
            for k in ("shipped", "returned"):
                if set(st[k]) != set(st["items"]):
                    raise ValueError
        except Exception:
            raise DepotError("BAD_SAVE")
        snap = self._st

        def f(_):
            self._st = st
        self._st = snap
        self._run(f)
