"""Depot: multi-warehouse inventory and cash ledger."""
import copy
import json

import events
import money
import suppliers
from events import emit, check_cash


class DepotError(Exception):
    def __init__(self, code):
        super().__init__(code)
        self.code = code


_STATE_KEYS = {
    "cash", "day", "items", "lots", "shipped", "returned", "shipments",
    "held_log", "fired", "notes", "overdrawn", "suppliers", "orders",
    "next_order",
}


class Depot:
    def __init__(self, warehouses, capacities, opening_cash, rounding_mode,
