from events import emit

START = 3
LOW, HIGH = 0, 5


def ensure(st, name):
    if name not in st["suppliers"]:
        st["suppliers"][name] = {"rel": START, "flagged": False}
    return st["suppliers"][name]


def is_suspended(st, name):
    return st["suppliers"][name]["rel"] <= 1


def adjust(st, name, delta):
    s = st["suppliers"][name]
    s["rel"] = max(LOW, min(HIGH, s["rel"] + delta))
    if s["rel"] <= 1 and not s["flagged"]:
        s["flagged"] = True
        emit(st, "SUPPLIER_SUSPENDED", name)


def reinstate(st, name):
    s = st["suppliers"][name]
    s["rel"] = 2
    s["flagged"] = False
