                    gone = sum(q for d, q in lots if today - d > shelf)
                    if gone:
                        st["lots"][sku][wh] = [
                            l for l in lots if today - l[0] <= shelf]
                        emit(st, "EXPIRY", sku, wh, gone)
            check_cash(st)
            st["held_log"][str(today)] = self._total_units()
        self._run(f, undoable=False)

    # ---------- suppliers ----------
    def place_order(self, supplier, sku, qty, due_day, wh=None):
        def f(st):
            self._sku(sku)
            self._qty(qty)
            target = wh if wh is not None else self._whs[0]
            self._wh(target)
            suppliers.ensure(st, supplier)
            if suppliers.is_suspended(st, supplier):
                raise DepotError("SUPPLIER_SUSPENDED")
            oid = st["next_order"]
            st["next_order"] += 1
            st["orders"][str(oid)] = {
                "supplier": supplier, "sku": sku, "qty": qty,
                "due": due_day, "wh": target, "done": False}
            return oid
        return self._run(f)

    def deliver(self, order_id, day):
        def f(st):
            o = st["orders"].get(str(order_id))
            if o is None:
                raise DepotError("UNKNOWN_ORDER")
            if o["done"]:
                raise DepotError("ALREADY_DELIVERED")
            late = day > o["due"]
            if late and self._late_pct is None:
                raise DepotError("LATE_PENALTY_UNSET")
            it = st["items"][o["sku"]]
            pay = money.delivery_payment(it["cost"], o["qty"], late,
                                         self._late_pct, self._mode)
            self._receive_core(o["sku"], o["qty"], o["wh"], pay)
            o["done"] = True
            suppliers.adjust(st, o["supplier"], -1 if late else 1)
        self._run(f)

    def reinstate(self, supplier):
        def f(st):
            if supplier not in st["suppliers"]:
                raise DepotError("UNKNOWN_SUPPLIER")
            suppliers.reinstate(st, supplier)
        self._run(f)

    def reliability(self, supplier):
        if supplier not in self._st["suppliers"]:
            raise DepotError("UNKNOWN_SUPPLIER")
        return self._st["suppliers"][supplier]["rel"]

    # ---------- queries ----------
    def stock(self, sku, wh=None):
        self._sku(sku)
        if wh is not None:
            self._wh(wh)
            return self._held(sku, wh)
        return sum(self._held(sku, w) for w in self._whs)

    def report(self):
        rows = []
        for sku in sorted(self._st["items"]):
            for wh in sorted(self._whs):
                u = self._held(sku, wh)
                rows.append((sku, wh, u, u * self._st["items"][sku]["cost"]))
        return rows

    def notifications(self):
        return [tuple(n) for n in self._st["notes"]]

    def turnover(self, start_day, end_day):
        st = self._st
        shipped = sum(q for d, q in st["shipments"]
                      if start_day <= d <= end_day)
        samples = []
        for d in range(start_day, end_day + 1):
            if d == st["day"]:
                samples.append(self._total_units())
            elif str(d) in st["held_log"]:
                samples.append(st["held_log"][str(d)])
        return money.turnover(shipped, samples)

    def audit(self, counts):
        def f(st):
            if not counts:
                raise DepotError("EMPTY_AUDIT")
            for (sku, wh) in counts:
                self._sku(sku)
                self._wh(wh)
            for (sku, wh) in sorted(counts):
                ledger = self._held(sku, wh)
                if ledger != counts[(sku, wh)]:
                    emit(st, "AUDIT_MISMATCH", sku, wh, ledger,
                         counts[(sku, wh)])
        self._run(f)

    # ---------- undo / persistence ----------
    def undo(self):
        if self._undo is None:
            raise DepotError("UNDO_BLOCKED")
        self._st = self._undo
        self._undo = None

    def save(self):
        return json.dumps({"version": 1, "state": self._st}, sort_keys=True)

    def load(self, s):
        try:
            d = json.loads(s)
            if not isinstance(d, dict) or d.get("version") != 1:
                raise ValueError("version")
            st = d["state"]
            if not isinstance(st, dict) or set(st) != _STATE_KEYS:
                raise ValueError("keys")
            if type(st["cash"]) is not int or type(st["day"]) is not int:
                raise ValueError("types")
            for sku, it in st["items"].items():
                if set(it) != {"cost", "reorder", "shelf"}:
                    raise ValueError("item")
                if set(st["lots"][sku]) != set(self._whs):
                    raise ValueError("lots")
                for lots in st["lots"][sku].values():
                    for d_, q in lots:
                        if type(d_) is not int or type(q) is not int:
                            raise ValueError("lot")
            for k in ("shipped", "returned"):
                if set(st[k]) != set(st["items"]):
                    raise ValueError(k)
        except Exception:
            raise DepotError("BAD_SAVE")
        self._run(lambda _: setattr(self, "_st", st), undoable=False)
