import decimal

import pytest

from inventory import Depot, DepotError
from sim import simulate

MODE = decimal.ROUND_HALF_EVEN


def make(cash=100000):
    d = Depot(["A", "B"], {"A": 100, "B": 100}, cash, MODE)
    d.add_item("BOLT", 12, 50)
    d.add_item("GLUE", 240, 5, shelf_life_days=7)
    return d


def code(fn, *a):
    with pytest.raises(DepotError) as e:
        fn(*a)
    return e.value.code


def test_C31_rounding_mode_required():
    with pytest.raises(TypeError):
        Depot(["A"], {"A": 10}, 100)


def test_C01_add_item_duplicate():
    d = make()
    assert code(d.add_item, "BOLT", 12, 50) == "DUPLICATE_SKU"


def test_C02_unknown_sku():
    d = make()
    assert code(d.receive, "NOPE", 1, "A") == "UNKNOWN_SKU"
    assert code(d.stock, "NOPE") == "UNKNOWN_SKU"


def test_C03_unknown_warehouse():
    d = make()
    assert code(d.receive, "BOLT", 1, "Z") == "UNKNOWN_WAREHOUSE"


def test_C04_receive_over_capacity():
    d = make()
    assert code(d.receive, "BOLT", 101, "A") == "CAPACITY"
    assert d.stock("BOLT") == 0


def test_C05_receive_insufficient_funds():
    d = make(cash=100)
    assert code(d.receive, "BOLT", 9, "A") == "INSUFFICIENT_FUNDS"
    assert d.cash == 100 and d.stock("BOLT") == 0
    d.receive("BOLT", 8, "A")
    assert d.cash == 4


def test_C06_ship_no_partial():
    d = make()
    d.receive("BOLT", 5, "A")
    assert code(d.ship, "BOLT", 6, "A", 100) == "INSUFFICIENT_STOCK"
    assert d.stock("BOLT", "A") == 5


def test_C07_ship_adds_cash():
    d = make()
    d.receive("BOLT", 5, "A")
    c = d.cash
    d.ship("BOLT", 2, "A", 100)
    assert d.cash == c + 200


def test_C08_list_price():
    d = make()
    assert d.list_price("BOLT") == 16
    assert d.list_price("GLUE") == 324


def test_C09_bulk_discount():
    d = make()
    d.receive("BOLT", 40, "A")
    c = d.cash
    d.ship("BOLT", 20, "A", 100)
    assert d.cash == c + 1800
    c = d.cash
    d.ship("BOLT", 19, "A", 100)
    assert d.cash == c + 1900


def test_C10_transfer_atomic():
    d = make()
    d.receive("BOLT", 10, "A")
    assert code(d.transfer, "BOLT", 11, "A", "B") == "INSUFFICIENT_STOCK"
    d.transfer("BOLT", 4, "A", "B")
    assert d.stock("BOLT", "A") == 6 and d.stock("BOLT", "B") == 4


def test_C10_transfer_capacity_at_destination():
    d = Depot(["A", "B"], {"A": 100, "B": 3}, 100000, MODE)
    d.add_item("BOLT", 12, 0)
    d.receive("BOLT", 10, "A")
    assert code(d.transfer, "BOLT", 5, "A", "B") == "CAPACITY"
    assert d.stock("BOLT", "A") == 10


def test_C12_fifo_expiry_of_oldest_lot():
    d = make()
    d.receive("GLUE", 3, "A")
    for _ in range(5):
        d.advance_day()
    d.receive("GLUE", 2, "A")
    for _ in range(3):
        d.advance_day()
    assert d.stock("GLUE") == 2
    assert ("EXPIRY", "GLUE", "A", 3) in d.notifications()


def test_C13_expiry_emitted():
    d = make()
    d.receive("GLUE", 4, "A")
    for _ in range(8):
        d.advance_day()
    assert d.stock("GLUE") == 0
    assert ("EXPIRY", "GLUE", "A", 4) in d.notifications()


def test_C14_reorder_once():
    d = make()
    d.receive("BOLT", 60, "A")
    d.ship("BOLT", 10, "A", 20)
    d.ship("BOLT", 1, "A", 20)
    assert d.notifications().count(("REORDER", "BOLT", "A")) == 1
    d.receive("BOLT", 20, "A")
    d.ship("BOLT", 30, "A", 20)
    assert d.notifications().count(("REORDER", "BOLT", "A")) == 2


def test_C15_supplier_on_time():
    d = make()
    oid = d.place_order("S", "BOLT", 5, 3)
    assert d.reliability("S") == 3
    d.deliver(oid, 2)
    assert d.reliability("S") == 4
    assert d.stock("BOLT") == 5


def test_C17_reinstate_sets_two():
    d = make()
    d.place_order("S", "BOLT", 5, 3)
    d.reinstate("S")
    assert d.reliability("S") == 2


def test_C19_storage_charge():
    d = make()
    d.receive("BOLT", 10, "A")
    c = d.cash
    d.advance_day()
    assert d.cash == c - 20


def test_C20_overdrawn_and_receive_blocked():
    d = make(cash=100)
    d.receive("BOLT", 8, "A")
    d.advance_day()
    assert d.cash < 0
    assert ("OVERDRAWN",) in d.notifications()
    assert code(d.receive, "BOLT", 1, "A") == "OVERDRAWN"


def test_C22_audit():
    d = make()
    d.receive("BOLT", 5, "A")
    d.audit({("BOLT", "A"): 4, ("BOLT", "B"): 0})
    assert d.notifications() == [("AUDIT_MISMATCH", "BOLT", "A", 5, 4)]
    assert code(d.audit, {}) == "EMPTY_AUDIT"


def test_C23_return_exceeds():
    d = make()
    d.receive("BOLT", 10, "A")
    d.ship("BOLT", 5, "A", 100)
    assert code(d.return_goods, "BOLT", 6, "A", 100) == "RETURN_EXCEEDS"
    c = d.cash
    d.return_goods("BOLT", 5, "A", 100)
    assert d.cash == c - 500
    assert d.stock("BOLT", "A") == 10


def test_C24_receive_bulk_all_or_nothing():
    d = make()
    assert code(d.receive_bulk,
                [("BOLT", 5, "A"), ("BOLT", 500, "B")]) == "CAPACITY"
    assert d.stock("BOLT") == 0
    d.receive_bulk([("BOLT", 5, "A"), ("BOLT", 6, "B")])
    assert d.stock("BOLT") == 11


def test_C25_stock_total_and_single():
    d = make()
    d.receive("BOLT", 3, "A")
    d.receive("BOLT", 4, "B")
    assert d.stock("BOLT") == 7
    assert d.stock("BOLT", "B") == 4


def test_C26_report_sorted():
    d = make()
    d.receive("GLUE", 2, "B")
    d.receive("BOLT", 3, "A")
    rows = d.report()
    assert rows == sorted(rows, key=lambda r: (r[0], r[1]))
    assert ("BOLT", "A", 3, 36) in rows
    assert ("GLUE", "B", 2, 480) in rows


def test_C27_undo_once_and_blocked_after_advance():
    d = make()
    d.receive("BOLT", 5, "A")
    c = d.cash
    d.ship("BOLT", 2, "A", 100)
    d.undo()
    assert d.stock("BOLT") == 5 and d.cash == c
    assert code(d.undo) == "UNDO_BLOCKED"
