    assert code(d.undo) == "UNDO_BLOCKED"


def test_C28_save_load_roundtrip_and_bad():
    d = make()
    d.receive("BOLT", 5, "A")
    s = d.save()
    d.receive("BOLT", 5, "A")
    d.load(s)
    assert d.stock("BOLT") == 5
    before = d.save()
    assert code(d.load, "not json") == "BAD_SAVE"
    assert code(d.load, '{"version": 2}') == "BAD_SAVE"
